def get_dip(bingrenzyid):
    url = f"http://192.168.9.26:9081/punuo/ba/ast/get/res-info?glwybs={bingrenzyid}&userId=DBA&source=doctor"
    retry_times = 3
    while retry_times > 0:
        try:
            with requests.Session() as session:
                r = session.get(url, timeout=30)
                r.raise_for_status()
                data = r.json()
            if data and (data.get('code', 1) == 0 or data.get('message', '') == "success"):
                return data.get('data')
        except Exception as e:
            logger.error(f"请求失败 {e.__str__()}，重试次数：{retry_times}")
            time.sleep(0.5)
            pass
        retry_times -= 1
    return None


"""刷新患者DIP数据"""

def refresh_patient_dip_info(bingrenzyid):
    redis_client = redis.Redis(connection_pool=pool)
    # 尝试设置更新锁
    if not redis_client.set(f"patient_dip_update_lock", 2, ex=90, nx=True):
        raise Exception("正在刷新，请稍后重试")

    patient_info = redis_client.hget('dip_all_patients', bingrenzyid)
    if not patient_info:
        redis_client.delete('patient_dip_update_lock')
        raise Exception('未找到患者信息')
    patient_info = json.loads(patient_info)
    dip = get_dip(bingrenzyid)
    if dip:
        dip_drg = dip.get('dipDrg') or {}
        # dip 分组
        patient_info['groupName'] = "{} {}".format(dip_drg.get('dipRzmc') or '', dip_drg.get('dipRz') or '').strip()
        # dip 诊断
        patient_info['zhenduan'] = "{} {}".format(dip_drg.get('dipZdmc') or '', dip_drg.get('dipZd') or '').strip()
        # dip倍率
        patient_info['dipRatio'] = dip_drg.get('dipJsFybl') or ''
        # 总费用
        patient_info['totalCost'] = dip_drg.get('zfy') or ''
        # 盈亏
        patient_info['profitLoss'] = dip_drg.get('dipJsJyyg') or ''
        # 标准分值
        patient_info['score1'] = dip_drg.get('dipMlfz') or ''
        # 校正分值
        patient_info['score2'] = dip_drg.get('dipJsJzfz') or ''

    redis_client.hset('dip_all_patients', bingrenzyid, json.dumps(patient_info, ensure_ascii=False, default=str))
    # redis_client.hset('all_dip_patients', bingrenzyid, json.dumps(patient_info, ensure_ascii=False, default=str))
    redis_client.delete('patient_dip_update_lock')
    return patient_info


def query_all_dip_record():
    start_time = time.time()
    redis_client = redis.Redis(connection_pool=pool)

    # 尝试获取更新锁
    if not redis_client.set("dip_query_lock", 1, ex=20*60, nx=True):
        raise Exception("正在获取数据，大概需要10-20分钟，请稍后重试")

    try:
        # 1. 查询主列表（约2000条）
        sql = """select zb.bingrenzyid, zb.xingming, zb.dangqianksmc, zb.zhuyuanysxm, gz.dianhua,zb.ruyuanrq , zb.chuyuanrq,zb.zaiyuanzt, 
case when exists  (
	select 1 from df_yiliaogl.gy_maidianrz gm where
		gm.mokuai = '病案首页'
		and gm.chuangjiansj<= zb.ruyuanrq + interval '3 day'
		and gm.xingwei = '保存'
		and gm.shujulyid = zb.bingrenzyid 
		 ) then 1 else 0 end as shouyebz,
case when exists  (
	select 1 from df_yiliaogl.gy_maidianrz gm where
		gm.mokuai = '病案首页'
		and gm.chuangjiansj>=now() - interval '1 day'
		and gm.xingwei = '保存'
		and gm.shujulyid = zb.bingrenzyid 
		 ) then 1 else 0 end as  today_update,
	(select string_agg(zz.zhenduanmc || '-' || zz.icd10 , '、' order by shunxuhao) from df_jj_zhuyuan.zy_zhenduanzl zz
	where zz.zuofeibz = '0'
		and zz.zhenduanlb like '13%'
		and zz.bingrenzyid = zb.bingrenzyid) zhenduan
		from df_jj_zhuyuan.zy_bingrenxx zb
		left join df_zhushuju.gy_zhigongda gz on zb.zhuyuanysid=gz.zhigongid
        where
	(zb.zaiyuanzt = '0' or zb.yuchuyrq>=now()-interval '1 day') --在院或当前时间24小时内出院
	and zb.xingming not like '%测试%'
	and zb.dangqianksmc not like '%测试%'
	and zb.dangqianbqmc not like '%测试%'
	and zb.quxiaorybz = '0'
        """

        data_list = global_tools.call_new_his_pg(sql)
        if not data_list:
            return

        logger.info(f'dip 一共查询到 {len(data_list)} 条总在院记录')

        # 1. 更新 入院三天未修改病案首页 患者列表
        redis_client.delete('dip_unpage_patients')
        pipe = redis_client.pipeline()
        count = 0
        for item in data_list:
            if item.get('shouyebz') == 1:
                redis_client.hset('dip_unpage_patients', item.get('bingrenzyid'),
                                  json.dumps(item, ensure_ascii=False, default=str))
                count += 1
                # 每 100 条提交一次 pipeline，防止内存积压
                if count % 30 == 0:
                    pipe.execute()
                    pipe = redis_client.pipeline()
        if count % 30 != 0:
            pipe.execute()

        # 2. 从列表中 删除出院患者
        for item in data_list:
            if item.get('zaiyuanzt') != 0:
                redis_client.hdel('dip_all_patients', item.get('bingrenzyid'))

        # 清空 今日更新患者列表
        redis_client.delete('dip_today_update_patients')

        # 3. 定义单个患者的处理函数（纯数据处理，不含IO）
        def process_item(item):
            try:
                patient_id = item.get('bingrenzyid')
                if not patient_id:
                    return None

                # 如果诊断没有变化 不更新
                if item.get('today_update') == 0:
                    if redis_client.exists('dip_all_patients', patient_id):
                        old_data = redis_client.hget('dip_all_patients', patient_id)
                        if old_data:
                            old_data = json.loads(old_data)
                            if item.get('zhenduan') == old_data.get('zhenduan'):
                                logger.info(f"患者 {patient_id} 的诊断没有变化，不更新")
                                return None

                dip = get_dip(patient_id)  # 此处为耗时操作，将被并发执行
                if dip:
                    dip_drg = dip.get('dipDrg') or {}
                    item['groupName'] = "{} {}".format(dip_drg.get('dipRzmc') or '', dip_drg.get('dipRz') or '').strip()
                    item['dip_zhenduan'] = "{} {}".format(dip_drg.get('dipZdmc') or '', dip_drg.get('dipZd') or '').strip()
                    item['dipRatio'] = dip_drg.get('dipJsFybl') or ''
                    item['totalCost'] = dip_drg.get('zfy') or ''
                    item['profitLoss'] = dip_drg.get('dipJsJyyg') or ''
                    item['score1'] = dip_drg.get('dipMlfz') or ''
                    item['score2'] = dip_drg.get('dipJsJzfz') or ''

                # 统一字段映射
                item['patientId'] = patient_id
                item['patientName'] = item.get('xingming', '')
                item['patientDept'] = item.get('dangqianksmc', '')
                item['zhuyuanysxm'] = item.get('zhuyuanysxm', '')
                item['ruyuanrq'] = item.get('ruyuanrq')
                item['zhenduan'] = item.get('zhenduan', '')
                item['zaiyuanzt'] = item.get('zaiyuanzt', 0)

                return item
            except Exception as e:
                logger.error(f"处理患者 {item.get('bingrenzyid')} 失败: {e}")
                return None

        # 3. 并发执行所有任务
        with ThreadPoolExecutor(max_workers=20) as executor:
            # 提交所有任务
            future_to_item = {executor.submit(process_item, item): item for item in data_list if item.get('zaiyuanzt') == 0}

            # 准备 Redis pipeline
            pipe = redis_client.pipeline()
            count = 0

            # 按完成顺序收集结果并批量写入 Redis
            for future in as_completed(future_to_item):
                result = future.result()
                if result:
                    key = result['bingrenzyid']
                    value = json.dumps(result, ensure_ascii=False, default=str)
                    pipe.hset('dip_all_patients', key, value)
                    if result.get('today_update', 0) == 1:
                        pipe.hset('dip_today_update_patients', key, value)
                    count += 1
                    # 每 100 条提交一次 pipeline，防止内存积压
                    if count % 100 == 0:
                        pipe.execute()
                        pipe = redis_client.pipeline()

            # 提交剩余未提交的命令
            if count % 100 != 0:
                pipe.execute()

        logger.info(f'dip 一共处理了 {count} 条有效记录, 总记录数 {len(data_list)}, 用时 {time.time() - start_time:.2f}秒')

    finally:
        # 无论成功或异常，务必释放锁
        redis_client.delete('dip_query_lock')




def ocr_try_variants(img_b64):
    """利用眼科医院的ocr识别工具进行解析（带重试机制）"""

    # 可配置参数
    max_retries = 3
    timeout = 10
    retry_delay = 1  # 重试间隔（秒）

    # 设置重试策略
    retry_strategy = Retry(
        total=max_retries,
        backoff_factor=retry_delay,
        status_forcelist=[500, 502, 503, 504],
        allowed_methods=["POST"]
    )

    session = requests.Session()
    adapter = HTTPAdapter(max_retries=retry_strategy)
    session.mount("http://", adapter)
    session.mount("https://", adapter)

    for attempt in range(1, max_retries + 1):
        try:
            payload = {"img_b64": img_b64}
            response = session.post(
                "http://192.168.190.252:8080/gyl/ehp/captcha",
                json=payload, timeout=timeout)
            response.raise_for_status()
            data = response.json()

            if data.get("code") == 20000:
                logger.debug(f"OCR 识别成功，第 {attempt} 次尝试")
                return data.get('data')
            else:
                logger.warning(
                    f"OCR 返回非成功码: code={data.get('code')}, "
                    f"msg={data.get('msg', 'N/A')}, 第 {attempt} 次尝试"
                )

        except requests.exceptions.Timeout:
            logger.error(f"OCR 请求超时，第 {attempt} 次尝试")
        except requests.exceptions.RequestException as e:
            logger.error(f"OCR 请求异常: {e}, 第 {attempt} 次尝试")
        except ValueError as e:
            logger.error(f"OCR 响应解析失败: {e}, 第 {attempt} 次尝试")

        # 最后一次不需要等待
        if attempt < max_retries:
            time.sleep(retry_delay * attempt)  # 指数退避

    session.close()
    raise Exception(f"OCR 识别失败，已重试 {max_retries} 次")


def safe_value(val, numeric=False):
    """安全处理参数值，避免空字符串传入数值字段"""
    if val is None:
        return None
    if numeric:
        # 数值类型：空字符串转为 None，否则保持原值（Decimal/float/int）
        if val == '':
            return None
        return val
    else:
        # 字符串类型：去除换行符并转为字符串
        return str(val).replace('\n', '').replace('\r', '')




